#include "../Source/Plugins/ReverbEditors.h"
#include <iostream>
#include <stdexcept>
static void check(bool x,const juce::String&m){if(!x)throw std::runtime_error(m.toStdString());}
static void set(hem::ModuleProcessor&p,const char*id,float value){auto*parameter=p.state.getParameter(id);check(parameter!=nullptr,"parameter missing");parameter->setValueNotifyingHost(parameter->convertTo0to1(value));}
static void save(const juce::Image&image,const juce::File&file){auto stream=file.createOutputStream();check(stream!=nullptr,"raster output file");stream->setPosition(0);stream->truncate();juce::PNGImageFormat format;check(format.writeImageToStream(image,*stream),"native PNG encoding");}
int main(int argc,char**argv){try{juce::ScopedJuceInitialiser_GUI gui;const auto folder=argc>1?juce::File(argv[1]):juce::File::getCurrentWorkingDirectory().getChildFile("reverb-native-rasters");check(folder.createDirectory().wasOk(),"raster directory");juce::MidiBuffer midi;
 for(int number:{19,20}){const auto approved=hem::ui::approvedFaceplate(number);check(approved.isValid(),"Approved reverb artwork is not embedded; shared integration is incomplete");std::unique_ptr<hem::ModuleProcessor>p=number==19?std::unique_ptr<hem::ModuleProcessor>(std::make_unique<hem::ConvolutionReverbProcessor>()):std::unique_ptr<hem::ModuleProcessor>(std::make_unique<hem::AlgorithmicReverbProcessor>());p->prepareToPlay(48000,128);auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());auto*module=dynamic_cast<hem::ModuleEditor*>(editor.get());check(module,"editor host contract");
 for(auto size:{juce::Point<int>(1000,563),juce::Point<int>(1280,720),juce::Point<int>(1672,941)}){editor->setSize(size.x,size.y);auto image=editor->createComponentSnapshot(editor->getLocalBounds(),true);check(image.isValid(),"native snapshot failed");save(image,folder.getChildFile(juce::String(number)+"-idle-"+juce::String(size.x)+".png"));if(size.x==1672){const std::vector<juce::Point<int>>centres=number==19?std::vector<juce::Point<int>>{{358,751},{556,751},{757,751},{963,751},{1166,751},{1348,751}}:std::vector<juce::Point<int>>{{125,679},{303,679},{483,679},{661,679},{839,679},{1018,679},{1194,679},{1372,679},{1549,679}};const int inner=number==19?63:60,outer=number==19?73:78;for(auto centre:centres)for(int y=centre.y-outer;y<=centre.y+outer;++y)for(int x=centre.x-outer;x<=centre.x+outer;++x){const int dx=x-centre.x,dy=y-centre.y,d=dx*dx+dy*dy;if(d<inner*inner||d>outer*outer||(number==19&&y>=806)||(number==20&&y>=744))continue;check(image.getPixelAt(x,y)==approved.getPixelAt(x,y),"authored dial ring/ticks were altered");}const auto meterPixel=image.getPixelAt(number==19?106:122,400);check(meterPixel.getGreen()<150,"idle meter retained pictured green signal");for(int side=0;side<2;++side){const auto aperture=number==19?juce::Rectangle<int>(side?1462:79,218,134,311):juce::Rectangle<int>(side?1441:112,140,117,307);int residual=0;for(int y=aperture.getY();y<aperture.getBottom();++y)for(int x=aperture.getX();x<aperture.getRight();++x){const auto colour=image.getPixelAt(x,y);if(colour.getGreen()>150&&colour.getGreen()>colour.getRed()*1.5&&colour.getGreen()>colour.getBlue()*1.5)++residual;}check(residual==0,"idle aperture retained part of the authored signal/glow");}}}
 if(number==19){const auto file=folder.getChildFile("owned-raster-impulse.wav");auto stream=file.createOutputStream();check(stream!=nullptr,"raster IR file");stream->setPosition(0);stream->truncate();juce::WavAudioFormat format;auto writer=std::unique_ptr<juce::AudioFormatWriter>(format.createWriterFor(stream.get(),48000,2,24,{},0));check(writer!=nullptr,"raster IR writer");stream.release();juce::AudioBuffer<float>ir(2,48000);for(int c=0;c<2;++c)for(int i=0;i<48000;++i)ir.setSample(c,i,.04f*std::exp(-float(i)/8000)*std::sin(float(i*(c?.37:.31))));check(writer->writeFromAudioSampleBuffer(ir,0,48000),"raster IR encode");writer.reset();check(static_cast<hem::ConvolutionReverbProcessor&>(*p).loadIRFileOffThread(file).wasOk(),"raster IR loading");}
 set(*p,"mix",45);juce::AudioBuffer<float>b(2,128);for(int block=0;block<600;++block){for(int c=0;c<2;++c)for(int i=0;i<128;++i)b.setSample(c,i,(block<100||(number==19&&block>560))?.2f*std::sin(float((block*128+i)*.04+c*.2)):0);p->processBlock(b,midi);if(block%10==0)module->refreshParameterActivity();}module->refreshParameterActivity();auto live=editor->createComponentSnapshot(editor->getLocalBounds(),true);save(live,folder.getChildFile(juce::String(number)+"-live.png"));const auto plot=number==19?juce::Rectangle<int>(330,245,1030,235):juce::Rectangle<int>(380,249,950,190);int cyan=0;for(int y=plot.getY();y<plot.getBottom();++y)for(int x=plot.getX();x<plot.getRight();++x){const auto colour=live.getPixelAt(x,y);if(colour.getGreen()>150&&colour.getBlue()>150&&colour.getRed()<80)++cyan;}check(cyan>50,"measured IR/tail plot failed to draw");editor.reset();p->releaseResources();}
 std::cout<<"PASS 2 native reverb editors: 6 idle + 2 live rasters, all authored dial rings preserved, idle meters cleared, loaded IR and measured tail visible\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
